(function() {
  var RAW = "data:image/png;base64,";

  function cleanLogo(uri, cb) {
    var img = new Image();
    img.onload = function() {
      var cv = document.createElement('canvas');
      cv.width  = img.naturalWidth;
      cv.height = img.naturalHeight;
      var ctx = cv.getContext('2d');
      ctx.drawImage(img, 0, 0);
      var id  = ctx.getImageData(0, 0, cv.width, cv.height);
      var px  = id.data;
      var THR = 55;
      for (var i = 0; i < px.length; i += 4) {
        var br = Math.max(px[i], px[i+1], px[i+2]);
        if (br < THR) { px[i+3] = Math.round((br / THR) * px[i+3]); }
      }
      ctx.putImageData(id, 0, 0);
      cb(cv.toDataURL('image/png'));
    };
    img.src = uri;
  }

  function inject() {
    cleanLogo(RAW, function(clean) {
      ['lx-logo-img','lx-form-logo-img','sb-logo-img','footer-logo-img','sg-logo-img','sg-form-logo-img'].forEach(function(id) {
        var el = document.getElementById(id);
        if (el) el.src = clean;
      });
    });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', inject);
  } else { inject(); }
})();
